// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CommunicationInteraction) predicate.CommunicationInteraction {
	return predicate.CommunicationInteraction(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CommunicationInteraction) predicate.CommunicationInteraction {
	return predicate.CommunicationInteraction(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CommunicationInteraction) predicate.CommunicationInteraction {
	return predicate.CommunicationInteraction(sql.NotPredicates(p))
}
